test.use({viewport:{width:1440,height:900},actionTimeout:8000,navigationTimeout:15000});
const errors=new WeakMap<Page,string[]>(),consoles=new WeakMap<Page,unknown[]>();
function listen(page:Page){if(errors.has(page))return;const e:string[]=[],c:unknown[]=[];errors.set(page,e);consoles.set(page,c);page.on('pageerror',x=>e.push(x.message));page.on('console',x=>{if(['error','warning'].includes(x.type()))c.push({type:x.type(),text:x.text()});});}
test.beforeEach(async({page})=>listen(page));
test.afterEach(async({page,context},info)=>{for(const p of context.pages())if(!p.isClosed())await p.evaluate(()=>{const w=window as any;w.__art06RestorePut?.();w.__art06ReleaseWrite?.();w.__art06RestoreRead?.();});await info.attach('art06-console',{body:JSON.stringify({errors:errors.get(page),console:consoles.get(page)}),contentType:'application/json'});expect(errors.get(page)).toEqual([]);});
async function database(page:Page){return page.evaluate(()=>new Promise<any>((resolve,reject)=>{const q=indexedDB.open('chenyuan-playable-v1');q.onerror=()=>reject(q.error);q.onsuccess=()=>{const db=q.result,tx=db.transaction([...db.objectStoreNames],'readonly'),rows:any={};for(const name of db.objectStoreNames){rows[name]=[];const read=tx.objectStore(name).openCursor();read.onsuccess=()=>{if(read.result){rows[name].push({key:read.result.key,value:read.result.value});read.result.continue();}};}tx.oncomplete=()=>{db.close();resolve({version:db.version,rows});};tx.onabort=()=>{db.close();reject(tx.error);};};}));}
async function load(page:Page,source:Game,virtual=true){await nativeHooks(page);if(virtual)await useJourneyClock(page);await page.goto('/');await expect(page.getByTestId('save-status')).toHaveText('尚无存档',{timeout:15000});await page.getByLabel('导入已有存档',{exact:true}).setInputFiles({name:'lawful-art06.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(source))});if(virtual)await finishJourneyClock(page);await expect(page.getByTestId('save-status')).toHaveText('已保存');const actual=await snapshot(page),expected=structuredClone(source);expect(actual.core.runId).not.toBe(source.core.runId);expected.core.runId=actual.core.runId;expected.core.revision=0;if(expected.core.activeEvent)expected.core.activeEvent.instanceId=actual.core.runId+':'+expected.core.activeEvent.id;expect(actual).toEqual(expected);return actual as Game;}
function mortal(){let g=newGame('潜修客','art06-mortal');for(const a of [{type:'CHOOSE',choice:'leave'},{type:'TRAVEL',location:'cave'}] as const)g=advance(g,{...a,commandId:'fixture-'+g.core.revision,runId:g.core.runId,expectedRevision:g.core.revision});return g;}
function caveFixture(){const d=driver();d.resource('herb',8);d.funds(100);d.go('cave');return d;}
function trialFixture(){const d=driver();while(d.game.core.player.realm!=='spirit')d.realm();prepareTrial(d);return d.checkpoints.trial as Game;}
async function unchanged(page:Page,g:Game,a:any,raw:any){const current=await database(page);expect(current).toEqual(raw);expect(current.rows['full-state'].find((r:any)=>r.key==='current').value).toEqual(g);expect(current.rows['full-state'].find((r:any)=>r.key==='activity')?.value??null).toEqual(a);}
async function capture(page:Page,info:TestInfo,name:string){await info.attach(name+'-dom',{body:await page.locator('body').innerText(),contentType:'text/plain'});await page.screenshot({path:info.outputPath(name+'.png')});}
async function quotaStart(page:Page){await page.evaluate(()=>{const w=window as any,put=IDBObjectStore.prototype.put;w.__art06RestorePut=()=>IDBObjectStore.prototype.put=put;IDBObjectStore.prototype.put=function(value:any,key?:IDBValidKey){if(this.transaction.db.name==='chenyuan-playable-v1'&&this.name==='full-receipts'&&value?.input?.kind==='START'){w.__art06Rejected={key,value:structuredClone(value)};w.__art06RestorePut();throw new DOMException('ART06 native START quota','QuotaExceededError');}return put.call(this,value,key!);};});}

const nativeReady=new WeakSet<Page>();
async function nativeHooks(page:Page){if(nativeReady.has(page))return;nativeReady.add(page);await page.addInitScript(()=>{const w=window as any,open=IDBFactory.prototype.open,put=IDBObjectStore.prototype.put;w.__art06Writes=[];IDBFactory.prototype.open=function(...args:any[]){const q=Reflect.apply(open,this,args);if(args[0]==='chenyuan-playable-v1')q.addEventListener('success',()=>{if(!w.__art06PrimaryDB)w.__art06PrimaryDB=q.result;});return q;};IDBObjectStore.prototype.put=function(value:any,key?:IDBValidKey){if(this.transaction.db.name==='chenyuan-playable-v1'&&this.name==='full-state'&&key==='current'){const row={wall:Date.now(),mono:performance.now(),game:structuredClone(value),committed:false};w.__art06Writes.push(row);this.transaction.addEventListener('complete',()=>{row.committed=true;});}return put.call(this,value,key!);};});}
async function settledLayout(page:Page){await expect.poll(()=>page.evaluate(()=>{const app=document.querySelector<HTMLElement>('.app-shell'),region=app?.querySelector<HTMLElement>('.stage-alerts');if(!app?.classList.contains('immersive-stage')||!region)return true;const h=region.getBoundingClientRect().height,n=parseFloat(app.style.getPropertyValue('--notice-height'));return Number.isFinite(n)&&Math.abs(n-(h?h+8:0))<=.5;}),{timeout:8000}).toBe(true);}
