async function receipt(page:Page,a:any,before:Game){const rows=(await database(page)).rows['full-receipts'].filter((r:any)=>r.key===a.runId+':'+a.nextCommand.commandId);expect(rows).toHaveLength(1);const r=rows[0].value,formal=resolve(before,a.nextCommand);expect(r.command).toEqual(a.nextCommand);expect(r.result).toEqual(formal.result);expect(r.activity).toEqual(completeActivity(formal.nextState,a,formal.result,{commandId:a.nextCommand.commandId,now:r.proof?.resolvedAt??r.activity.startedAt??a.dueAt}));if(a.version===7){expect(r.proof.activityBefore).toEqual(a);expect(r.proof.stateAfter).toEqual(formal.nextState);expect(r.proof.resolvedAt).toBeGreaterThanOrEqual(a.dueAt);}else{expect(a.version).toBe(1);expect(r.version).toBe(1);expect(r.proof).toBeUndefined();}return rows[0];}
async function begin(page:Page,id='training-start',virtual=true){await page.getByTestId(id).click();await expect.poll(async()=>(await activity(page))?.status).toBe('running');const a=await activity(page);await expect(page.locator('[data-testid=training-activity][data-generation="'+a.generation+'"][data-running=true]')).toBeVisible();if(virtual)await expect(page.getByTestId('training-countdown')).toHaveText((a.cycleMs/1000).toFixed(1)+' 秒');else{await expect(page.getByTestId('training-countdown')).toBeVisible();const remaining=parseFloat(await page.getByTestId('training-countdown').innerText());expect(remaining).toBeGreaterThan(0);expect(remaining).toBeLessThanOrEqual(a.cycleMs/1000);expect(a.dueAt-a.startedAt).toBe(a.cycleMs);await expect(page.getByRole('progressbar',{name:'本轮活动进度',exact:true})).toHaveAttribute('aria-valuemax',String(a.cycleMs));}return a;}
async function tick(page:Page,a:any,before:Game){const left=a.dueAt-await page.evaluate(()=>Date.now());expect(left).toBeGreaterThan(0);await page.clock.fastForward(left-1);expect(await snapshot(page)).toEqual(before);expect((await database(page)).rows['full-receipts'].filter((r:any)=>r.key===a.runId+':'+a.nextCommand.commandId)).toEqual([]);await page.clock.fastForward(1);await expect.poll(async()=>(await activity(page)).completedCycles).toBe(a.completedCycles+1);const after=await snapshot(page);expect(after).toEqual(advance(before,a.nextCommand));await receipt(page,a,before);await expect.poll(async()=>{await page.clock.runFor(16);return page.getByTestId('save-status').innerText();}).toBe('已保存');return after as Game;}
async function hold(page:Page){await page.evaluate(()=>new Promise<void>((resolve,reject)=>{const q=indexedDB.open('chenyuan-playable-v1');q.onerror=()=>reject(q.error);q.onsuccess=()=>{const db=q.result,tx=db.transaction('full-state','readwrite');let holding=true,ready=false;const w=window as any;w.__art06ReleaseWrite=()=>holding=false;function read(){const r=tx.objectStore('full-state').get('current');r.onsuccess=()=>{w.__art06HeldGame=r.result;if(!ready){ready=true;resolve();}if(holding)read();};}read();tx.oncomplete=()=>db.close();tx.onabort=()=>{db.close();reject(tx.error);};};}));}
async function cycleFault(page:Page,mode:'quota'|'abort'){await page.evaluate(mode=>{const w=window as any,put=IDBObjectStore.prototype.put;w.__art06RestorePut=()=>IDBObjectStore.prototype.put=put;IDBObjectStore.prototype.put=function(value:any,key?:IDBValidKey){if(this.transaction.db.name==='chenyuan-playable-v1'&&this.name==='full-state'&&key==='current'){w.__art06RestorePut();w.__art06CycleRejected={value:structuredClone(value),key};if(mode==='quota')throw new DOMException('ART06 real cycle quota','QuotaExceededError');const result=put.call(this,value,key!);result.addEventListener('success',()=>this.transaction.abort(),{once:true});return result;}return put.call(this,value,key!);};},mode);}
const resultSelectors='[data-testid=cultivation-result],[data-testid=milestone-result],[data-testid=milestone-handoff]';
async function observe(page:Page){await page.evaluate(selector=>{const w=window as any,seen=new WeakMap<Element,string>(),rows:any[]=[];function collect(root:Node){if(!(root instanceof Element))return;for(const e of root.matches(selector)?[root]:root.querySelectorAll(selector)){const sequence=e.getAttribute('data-sequence');if(sequence&&seen.get(e)!==sequence){seen.set(e,sequence);rows.push({id:e.getAttribute('data-testid'),sequence,text:e.textContent,wall:Date.now()});}}}const observer=new MutationObserver(cs=>{for(const c of cs)if(c.type==='attributes')collect(c.target);else for(const n of c.addedNodes)collect(n);});observer.observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['data-sequence']});w.__art06Observer=observer;w.__art06Effects=rows;},resultSelectors);}
async function effects(page:Page){return page.evaluate(()=>(window as any).__art06Effects??[]);}
async function noEffect(page:Page){await expect(page.locator(resultSelectors)).toHaveCount(0);}
async function coldSite(page:Page,saving=false){const site=page.getByTestId('cultivation-site');await expect(site).toHaveAttribute('data-working','false');for(const stream of await site.locator('.art06-spirit-stream').all()){await expect(stream).toHaveCSS('opacity','0');await expect(stream).toHaveCSS('animation-name','none');}await expect(site.locator('.art06-meditator')).toHaveCSS('animation-name','none');await expect(site.locator('.art06-breath')).toHaveCSS('animation-name','none');await expect(site.locator('.art06-breath')).toHaveCSS('opacity',saving?'0.5':'0');}
async function form(page:Page,method:'natural'|'assisted'='natural'){await openCultivation(page,method);const box=page.getByTestId('training-limits');if(await box.count()&&!await box.evaluate(n=>(n as HTMLDetailsElement).open))await page.getByTestId('training-limits-toggle').click();await expect(page.getByLabel('修行目标',{exact:true})).toBeVisible();}
async function openTrainingBudget(page:Page){const box=page.getByTestId('training-limits');if(!await box.evaluate(n=>(n as HTMLDetailsElement).open))await page.getByTestId('training-limits-toggle').click();await expect(page.getByLabel('累计灵石预算',{exact:true})).toBeVisible();await expect(page.getByLabel('灵石保留量',{exact:true})).toBeVisible();}
async function closeForm(page:Page){const box=page.getByTestId('training-limits');if(await box.count()&&await box.evaluate(n=>(n as HTMLDetailsElement).open))await page.getByTestId('training-limits-toggle').click();}
async function selectGoal(page:Page,value:string){await selectTrackedGoal(page,value);await expect(page.getByTestId('goal-select')).toHaveValue(value);await expect(page.getByTestId('goal-object-board')).toBeVisible();}
async function setup(page:Page,method:'natural'|'assisted',target='1',budget=0,reserve=0){await form(page,method);await page.getByLabel('修行目标',{exact:true}).selectOption(target);await openTrainingBudget(page);await page.getByLabel('累计灵石预算',{exact:true}).fill(String(budget));await page.getByLabel('灵石保留量',{exact:true}).fill(String(reserve));await closeForm(page);}
async function clearances(page:Page,info:TestInfo,name:string){const rows=await page.locator(resultSelectors).evaluateAll(nodes=>{const vis=(e:Element)=>{if(!e.getClientRects().length||getComputedStyle(e).visibility==='hidden')return false;for(let p=e.parentElement;p;p=p.parentElement)if(p instanceof HTMLDetailsElement&&!p.open&&!p.querySelector(':scope>summary')?.contains(e))return false;return true;},rect=(e:Element)=>e.getBoundingClientRect(),targets=[...document.querySelectorAll('main button,#primary-navigation button,.training-choice,.training-budget,[data-testid=cultivation-cycle-clock],.reading-text,[data-testid=milestone-material]')].filter(vis);return nodes.filter(vis).map(e=>{const r=rect(e),p=e.parentElement!,b=rect(p);const actor=e.getAttribute('data-testid')==='cultivation-result'?document.querySelector('.art06-meditator'):null,actorRect=actor?rect(actor):null;return{id:e.getAttribute('data-testid'),text:e.textContent,font:parseFloat(getComputedStyle(e).fontSize),primary:[...e.querySelectorAll('strong')].map(n=>({text:n.textContent,font:parseFloat(getComputedStyle(n).fontSize)})),rect:{left:r.left,right:r.right,top:r.top,bottom:r.bottom},actor:actorRect?{left:actorRect.left,right:actorRect.right,top:actorRect.top,bottom:actorRect.bottom}:null,actorArea:actorRect?Math.max(0,Math.min(r.right,actorRect.right)-Math.max(r.left,actorRect.left))*Math.max(0,Math.min(r.bottom,actorRect.bottom)-Math.max(r.top,actorRect.top)):0,opacity:getComputedStyle(e).opacity,inside:r.left>=b.left-.5&&r.right<=b.right+.5&&r.top>=b.top-.5&&r.bottom<=b.bottom+.5,clashes:targets.filter(n=>!n.contains(e)&&!e.contains(n)).map(n=>{const x=rect(n);return{text:n.textContent,area:Math.max(0,Math.min(r.right,x.right)-Math.max(r.left,x.left))*Math.max(0,Math.min(r.bottom,x.bottom)-Math.max(r.top,x.top))};}).filter(n=>n.area>0)};});});await info.attach(name+'-result-clearance',{body:JSON.stringify(rows),contentType:'application/json'});for(const r of rows){expect(r.opacity).toBe('1');expect(r.font,r.text??'').toBeGreaterThanOrEqual(14);expect(r.inside,r.text??'').toBe(true);for(const p of r.primary)expect(p.font,p.text??'').toBeGreaterThanOrEqual(18);if(r.id==='cultivation-result'){expect(r.actor,'actual seated practitioner rectangle').not.toBeNull();expect(r.actorArea,'saved cultivation text cannot cover the practitioner').toBe(0);}expect(r.clashes,r.text??'').toEqual([]);}}
async function realCycle(page:Page,info:TestInfo,before:Game,a:any,result:string,name:string){const started=await page.evaluate(()=>({wall:Date.now(),mono:performance.now()})),first=parseFloat(await page.getByTestId('training-countdown').innerText());await expect(page.getByTestId(a.version===1?'cultivation-cycle-clock':'milestone-cycle-clock')).toBeVisible();await expect.poll(async()=>parseFloat(await page.getByTestId('training-countdown').innerText())).toBeLessThan(first);expect(await snapshot(page)).toEqual(before);await noEffect(page);await picture(page,info,name+'-real-running');await expect.poll(async()=>(await activity(page)).completedCycles,{timeout:a.cycleMs+5000}).toBe(1);const after=await snapshot(page),formal=resolve(before,a.nextCommand),writes=await page.evaluate(()=>(window as any).__art06Writes),committed=writes.filter((r:any)=>r.game.core.runId===before.core.runId&&r.game.core.revision===before.core.revision+1);expect(after).toEqual(formal.nextState);expect(committed).toHaveLength(1);expect(committed[0].wall).toBeGreaterThanOrEqual(a.dueAt);expect(committed[0].game).toEqual(after);expect(committed[0].committed).toBe(true);await receipt(page,a,before);await expect(page.getByTestId(result)).toBeVisible();await expect(page.locator(resultSelectors)).toHaveCount(1);await clearances(page,info,name);await picture(page,info,name+'-real-saved');await info.attach(name+'-real-cycle-proof',{body:JSON.stringify({started,ended:await page.evaluate(()=>({wall:Date.now(),mono:performance.now()})),activity:a,committed,after,formalResult:formal.result,effects:await effects(page)}),contentType:'application/json'});return after as Game;}

test('ART06-A4 one real thirty second natural cycle moves only the formal saved cultivation and preserves a static result without an automatic breakthrough',async({page},info)=>{
 const before=await load(page,mortal(),false);await setup(page,'natural');const raw=await database(page);await unchanged(page,before,null,raw);await observe(page);const a=await begin(page,'training-start',false);expect(a.cycleMs).toBe(30000);expect(a.version).toBe(1);const after=await realCycle(page,info,before,a,'cultivation-result','natural');expect(after.core.player.xp).toBe(5);expect(after.core.player.realm).toBe('mortal');expect(after.core.player.stones).toBe(before.core.player.stones);expect((await activity(page)).status).toBe('stopped');await expect(page.getByTestId('training-summary')).toBeVisible();const saved=await database(page);await page.reload();await expect(page.getByTestId('save-status')).toHaveText('已保存');await noEffect(page);expect(await database(page)).toEqual(saved);
});

