test('ART06-A7 native saving and a held pause keep cultivation cold and truthful until exactly one complete Game is committed then no next cycle starts',async({page},info)=>{
 const before=await load(page,caveFixture().game);await setup(page,'natural','5');await observe(page);const a=await begin(page),left=a.dueAt-await page.evaluate(()=>Date.now());await page.clock.fastForward(left-1);expect(await snapshot(page)).toEqual(before);await hold(page);let failure:unknown;try{await page.clock.fastForward(1);await expect(page.getByTestId('save-status')).toHaveText('保存中');await expect(page.getByTestId('cultivation-site')).toHaveAttribute('data-state','saving');await expect(page.getByTestId('cultivation-site')).toHaveAttribute('data-working','false');expect(await page.evaluate(()=>(window as any).__art06HeldGame)).toEqual(before);await noEffect(page);await coldSite(page,true);await picture(page,info,'cultivation-native-saving');await page.getByTestId('training-pause').click();await expect(page.getByTestId('training-activity')).toContainText('正在暂停');await noEffect(page);await expect(page.getByTestId('cultivation-site')).toHaveAttribute('data-working','false');await coldSite(page);await picture(page,info,'cultivation-pause-pending');}catch(error){failure=error;}finally{await page.evaluate(()=>(window as any).__art06ReleaseWrite());}if(failure)throw failure;await expect.poll(async()=>(await activity(page)).status).toBe('paused');const after=await snapshot(page);expect(after).toEqual(advance(before,a.nextCommand));expect((await activity(page)).completedCycles).toBe(1);await receipt(page,a,before);await noEffect(page);const raw=await database(page);await page.clock.fastForward(120000);await unchanged(page,after,await activity(page),raw);
});

