test('ART06-A9 native quota and put-success abort preserve the whole cultivation DB and the original exact cycle retries its first real outcome once',async({browser},info)=>{
 for(const mode of ['quota','abort'] as const){const context=await browser.newContext({baseURL:'http://127.0.0.1:4173',viewport:{width:1440,height:900}}),page=await context.newPage();listen(page);try{const before=await load(page,mortal());await setup(page,'natural');await observe(page);const a=await begin(page),raw=await database(page);await cycleFault(page,mode);await page.clock.fastForward(a.cycleMs);await expect(page.getByTestId('error')).toBeVisible();await unchanged(page,before,a,raw);await noEffect(page);await expect(page.getByTestId('cultivation-site')).toHaveAttribute('data-working','false');expect(await page.evaluate(()=>(window as any).__art06CycleRejected)).toBeTruthy();await coldSite(page);await picture(page,info,'cultivation-'+mode+'-no-outcome');await page.getByTestId('retry').click();await expect.poll(async()=>(await activity(page)).completedCycles).toBe(1);const after=await snapshot(page);expect(after).toEqual(advance(before,a.nextCommand));await receipt(page,a,before);await expect.poll(async()=>{await page.clock.runFor(16);return page.getByTestId('cultivation-result').count();}).toBe(1);await clearances(page,info,'cultivation-'+mode+'-retry');expect((await effects(page)).filter((r:any)=>r.id==='cultivation-result')).toHaveLength(1);const saved=await database(page);await page.clock.fastForward(120000);expect(await snapshot(page)).toEqual(after);expect(await database(page)).toEqual(saved);await noEffect(page);await page.reload();await expect(page.getByTestId('save-status')).toHaveText('已保存');await openCultivation(page);await noEffect(page);expect(await database(page)).toEqual(saved);expect(errors.get(page)).toEqual([]);}finally{await info.attach(mode+'-console',{body:JSON.stringify({errors:errors.get(page),console:consoles.get(page)}),contentType:'application/json'});await context.close();}}
});

test('ART06-A10 a same-id foreign takeover and a hidden later cycle never replay local aura and refresh requires a newly authorized full cycle',async({page,context},info)=>{
 const before=await load(page,caveFixture().game);await setup(page,'natural','5');const other=await context.newPage();listen(other);try{await useJourneyClock(other);await other.goto('/');await expect(other.getByTestId('save-status')).toHaveText('已保存');await observe(page);const a=await begin(page),first=await tick(page,a,before);await expect(page.getByTestId('cultivation-result')).toBeVisible();const original=await activity(page);await other.getByTestId('training-resume').click();await expect.poll(async()=>(await activity(other)).generation).toBeGreaterThan(original.generation);const taken=await activity(other);expect(taken.id).toBe(original.id);expect(taken.ownerId).not.toBe(original.ownerId);await expect(page.locator('[data-testid=training-activity][data-generation="'+taken.generation+'"]')).toBeVisible();expect(await page.evaluate(()=>document.hidden)).toBe(false);await noEffect(page);await expect(page.getByTestId('cultivation-site')).toHaveAttribute('data-working','false');expect(await snapshot(page)).toEqual(first);await coldSite(page);await picture(page,info,'same-id-takeover-no-old-aura');await other.getByTestId('training-pause').click();await expect.poll(async()=>(await activity(page)).status).toBe('paused');await page.getByTestId('training-resume').click();const own=await activity(page);await expect(page.locator('[data-testid=training-activity][data-generation="'+own.generation+'"][data-running=true]')).toBeVisible();await page.evaluate(()=>{Object.defineProperty(document,'hidden',{configurable:true,get:()=>true});document.dispatchEvent(new Event('visibilitychange'));});await noEffect(page);const second=await tick(page,own,first);await page.evaluate(()=>{delete (document as any).hidden;document.dispatchEvent(new Event('visibilitychange'));});await noEffect(page);await page.getByTestId('training-pause').click();await expect.poll(async()=>(await activity(page)).status).toBe('paused');const saved=await database(page);await page.reload();await expect(page.getByTestId('save-status')).toHaveText('已保存');await openCultivation(page);await noEffect(page);await page.clock.fastForward(86400000);expect(await snapshot(page)).toEqual(second);expect(await database(page)).toEqual(saved);await page.getByTestId('training-resume').click();const resumed=await activity(page);expect(resumed.nextCommand.commandId).not.toBe(own.nextCommand.commandId);await expect(page.getByTestId('training-countdown')).toHaveText('60.0 秒');await page.clock.fastForward(59999);expect(await snapshot(page)).toEqual(second);await page.getByTestId('training-pause').click();await expect.poll(async()=>(await activity(page)).status).toBe('paused');await receipt(page,a,before);await receipt(page,own,first);expect(errors.get(other)).toEqual([]);}finally{await other.close();}
});

