 const d=driver();d.event('lu_intro','listen');d.go('cave');const before=await load(page,d.game),raw=await database(page),events=[...new Set([...Object.keys(before.choices),...availableEvents(before).map(e=>e.id)])];await openHubFeature(page,'goal');const targets=[...Object.keys(C.items).map(id=>({value:'item:'+id,target:{kind:'item',id,quantity:1}})),...Object.keys(C.skills).map(id=>({value:'skill:'+id,target:{kind:'skill',id}})),...Object.keys(C.relics).map(id=>({value:'relic:'+id,target:{kind:'relic',id}})),...events.map(id=>({value:'event:'+id,target:{kind:'event',id}}))];
