test('ART06-A17 opening through the ordinary current detail keeps the medicine case all three full choices and its one six second result then an actionable next step',async({page},info)=>{
 const before=await load(page,newGame('雨庙来客','art06-current-opening')),raw=await database(page);await page.getByRole('button',{name:'查看三种选择与剑简说明',exact:true}).click();await expect(page.locator('#feature-title')).toHaveText('当前遭遇');for(const[choice,label]of [['help','赠丹相助'],['trade','以丹换简'],['leave','保留丹药']]as const){const preview=previewAction(before,{type:'CHOOSE',choice});expect(preview.allowed).toBe(true);await expect(page.getByTestId(choice)).toBeVisible();await expect(page.getByTestId(choice)).toContainText(label);await expect(page.getByTestId(choice)).toContainText(formatCosts(preview.costs));}await unchanged(page,before,null,raw);await picture(page,info,'ordinary-opening-all-choices');expect(await page.getByTestId('milestone-gate').filter({visible:true}).count(),'ordinary current opening has its actual medicine-case object').toBe(1);await page.getByTestId('trade').click();await expect(page.getByTestId('milestone-review')).toContainText('以丹换简');await unchanged(page,before,null,raw);await observe(page);const a=await begin(page,'milestone-confirm');expect(a.plan.action).toEqual({type:'CHOOSE',choice:'trade'});expect(a.cycleMs).toBe(6000);await expect(page.getByTestId('milestone-cycle-clock')).toBeVisible();const after=await tick(page,a,before);expect(after.core.player.realm).toBe('mortal');expect(after.core.inventory.healing_pill).toBe(before.core.inventory.healing_pill-1);expect(after.core.learnedSkills).toEqual([C.swordManual.id]);expect(after.core.openingChoice).toBe('trade');await expect(page.getByTestId('milestone-handoff')).toBeVisible();await expect(page.getByTestId('return-cave')).toBeVisible();await picture(page,info,'ordinary-opening-saved-next-step');await expect(page.locator('#primary-navigation button')).toHaveCount(8);if(await page.getByTestId('hub-close').isVisible())await page.getByTestId('hub-close').click();await expect(page.getByTestId('return-cave')).toBeEnabled();expect(await snapshot(page)).toEqual(after);await receipt(page,a,before);
});

