 await openHubFeature(page,'forge');const first=await income();await expect(first).toBeEnabled();await openHubFeature(page,'forge');await selectAlchemyRecipe(page,'healing');await expect(page.getByTestId('production-start')).toBeEnabled();const raw=await database(page);await quotaStart(page);await page.getByTestId('production-start').click();await expect(page.getByTestId('error')).toContainText('存储空间不足');await expect(page.getByTestId('retry')).toBeEnabled();const rejected=await page.evaluate(()=>(window as any).__art06Rejected);expect(rejected.value.input.plan).toMatchObject({kind:'craft',recipeId:'healing'});await unchanged(page,before,null,raw);await closeProductionSettings(page);const foreign=await income();await expect(page.getByTestId('preparation-compare')).toBeEnabled();await expect(foreign).toBeDisabled();if(await foreign.isEnabled())await foreign.click();await unchanged(page,before,null,raw);await expect(page.getByTestId('retry')).toBeEnabled();let failure:unknown;try{await picture(page,info,'pending-craft-preparation-income-route');}catch(error){failure=error;}await page.getByTestId('retry').click();await expect.poll(async()=>(await activity(page))?.status).toBe('running');const accepted=await activity(page),saved=await database(page);expect(accepted.plan).toEqual(rejected.value.input.plan);expect(saved.rows['full-receipts'].find((r:any)=>r.key===rejected.key).value.input).toEqual(rejected.value.input);await page.getByTestId('training-pause').click();await expect.poll(async()=>(await activity(page)).status).toBe('paused');expect(await snapshot(page)).toEqual(before);await info.attach('pending-preparation-travel-original-intent',{body:JSON.stringify({before,raw,rejected,accepted,saved}),contentType:'application/json'});if(failure)throw failure;
